// 取引マッチングと鑑定ステータス遷移のロジック
// 買い手からの入金完了 ➔ 売り手に発送指示 ➔ 自社ハブ到着 ➔ 鑑定合格 ➔ 売り手へ着金＋購入者へ発送
async function processTransaction(order) {
  await holdBuyerFundsInEscrow(order);
  await verifyItemInAuthenticationCenter(order.itemId);
  await attachGreenVerificationTag(order.itemId);
  await releaseSellerPayoutMinusFee(order.sellerId, order.price * 0.90); // 手数料10%控除
}
